(function(){"use strict";var refocusNew=false;function isCell(el){return el&&el.classList&&el.classList.contains("cell")&&!el.classList.contains("cell--new");}
function cells(){return Array.prototype.filter.call(document.querySelectorAll("input.cell"),function(el){return!el.disabled&&el.offsetParent!==null;});}
function mark(input,ok){input.removeAttribute("aria-busy");input.classList.toggle("is-invalid",!ok);if(ok){input.removeAttribute("aria-invalid");input.classList.add("is-saved");setTimeout(function(){input.classList.remove("is-saved");},1600);}else{input.setAttribute("aria-invalid","true");}}
function save(input){var form=input.form;if(!form||!window.htmx)return;var values={campo:input.name};values[input.name]=input.value;Array.prototype.forEach.call(form.elements,function(el){if(el.type==="hidden"&&el.name)values[el.name]=el.value;});input.setAttribute("aria-busy","true");window.htmx.ajax("POST",form.getAttribute("action"),{source:input,values:values,swap:"none"});}
var TRANSPORT_MSG={0:"Sem conexão: não salvou. Confira a internet e saia do campo de novo.",400:"A página expirou: não salvou. Recarregue a página e digite de novo.",429:"Muitas tentativas seguidas: não salvou. Espere um pouco e saia do campo de novo.",500:"Erro no servidor: não salvou. Tente de novo em instantes."};function explainFailure(xhr){var code=xhr?xhr.status:0;if(code===401&&xhr.getResponseHeader("HX-Redirect"))return;if(xhr&&/id="salvo-status"/.test(xhr.responseText||""))return;var status=document.getElementById("salvo-status");if(!status)return;status.textContent=TRANSPORT_MSG[code]||(code>=500?TRANSPORT_MSG[500]:"Não salvou. Recarregue a página e tente de novo.");status.classList.add("save-status--error");status.setAttribute("role","alert");}
document.addEventListener("htmx:afterRequest",function(event){var input=event.target;if(!isCell(input))return;var xhr=event.detail&&event.detail.xhr;var ok=!!(xhr&&xhr.status>=200&&xhr.status<300);if(ok)input.setAttribute("data-orig",input.value);mark(input,ok);if(!ok)explainFailure(xhr);});document.addEventListener("focusin",function(event){var input=event.target;if(isCell(input)&&!input.hasAttribute("aria-busy")){if(!input.hasAttribute("data-orig"))input.setAttribute("data-orig",input.defaultValue);}});document.addEventListener("keydown",function(event){var input=event.target;if(!isCell(input))return;if(event.key==="Enter"){event.preventDefault();var all=cells();var next=all[all.indexOf(input)+1];if(next){next.focus();if(next.select)next.select();}else{input.blur();}}else if(event.key==="Escape"){event.preventDefault();input.value=input.getAttribute("data-orig")||"";input.classList.remove("is-invalid");input.removeAttribute("aria-invalid");input.blur();}});document.addEventListener("focusout",function(event){var input=event.target;if(isCell(input)){var orig=input.hasAttribute("data-orig")?input.getAttribute("data-orig"):input.defaultValue;if(input.value!==orig)save(input);return;}
if(input&&input.classList&&input.classList.contains("cell--new")){var row=input.closest("tr");setTimeout(function(){if(row&&row.contains(document.activeElement))return;var name=document.getElementById("nova-nome");var form=document.getElementById("f-nova");if(name&&form&&name.value.trim()){refocusNew=true;form.requestSubmit();}},0);}});document.addEventListener("htmx:afterSettle",function(){if(!refocusNew)return;refocusNew=false;var name=document.getElementById("nova-nome");if(name&&!name.value)name.focus();});document.addEventListener("submit",function(event){if(event.target&&event.target.matches&&event.target.matches("[data-new-form]"))refocusNew=true;});var GAP=8;function plain(text){return String(text||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");}
function openWhos(){return document.querySelectorAll("details.who[open]");}
function closeWhos(except){Array.prototype.forEach.call(openWhos(),function(d){if(d!==except)d.removeAttribute("open");});}
function placeWho(details){var summary=details.querySelector("summary");var panel=details.querySelector(".who__panel");if(!summary||!panel)return;var r=summary.getBoundingClientRect();var w=panel.offsetWidth;var h=panel.offsetHeight;var left=Math.max(GAP,Math.min(r.left,window.innerWidth-w-GAP));var top=r.bottom+GAP/2;if(top+h>window.innerHeight-GAP&&r.top-h-GAP/2>GAP)top=r.top-h-GAP/2;panel.style.left=left+"px";panel.style.top=top+"px";}
document.addEventListener("toggle",function(event){var d=event.target;if(!d||!d.matches||!d.matches("details.who")||!d.open)return;closeWhos(d);var search=d.querySelector("[data-who-search]");if(search){search.value="";filterWho(search);}
placeWho(d);if(search)search.focus({preventScroll:true});},true);function filterWho(box){var panel=box.closest(".who__panel");var q=plain(box.value);var any=false;Array.prototype.forEach.call(panel.querySelectorAll("[data-who-item]"),function(li){var hit=!q||plain(li.getAttribute("data-search")).indexOf(q)!==-1;li.hidden=!hit;any=any||hit;});var none=panel.querySelector(".who__none");if(none)none.hidden=any;}
document.addEventListener("input",function(event){var box=event.target;if(box&&box.matches&&box.matches("[data-who-search]"))filterWho(box);});document.addEventListener("keydown",function(event){if(event.key==="Enter"&&event.target.matches&&event.target.matches("[data-who-search]")){event.preventDefault();return;}
if(event.key!=="Escape")return;var open=openWhos();if(!open.length)return;var summary=open[0].querySelector("summary");closeWhos(null);if(summary)summary.focus();});document.addEventListener("click",function(event){if(!openWhos().length)return;closeWhos(event.target.closest?event.target.closest("details.who"):null);});function followWhos(){Array.prototype.forEach.call(openWhos(),function(d){var r=d.querySelector("summary").getBoundingClientRect();if(r.bottom<0||r.top>window.innerHeight)d.removeAttribute("open");else placeWho(d);});}
window.addEventListener("scroll",followWhos,{passive:true});window.addEventListener("resize",followWhos);document.addEventListener("change",function(event){var form=event.target&&event.target.closest?event.target.closest("form[data-autosubmit]"):null;if(form)form.requestSubmit();});})();